beforeExample:
import java.io.ByteArrayOutputStream;
import java.io.OutputStream;
import org.eclipse.debug.internal.core.InputStreamMonitor;

public class Example {
    public void test() {
        OutputStream os = new ByteArrayOutputStream();
        // This constructor was marked @Deprecated for using String encoding
        InputStreamMonitor monitor1 = new InputStreamMonitor(os, "UTF-8");
        // If encodingString is null, Charset.forName(null) would throw NullPointerException,
        // which mirrors the behavior of the original deprecated constructor's internal call.
        InputStreamMonitor monitor2 = new InputStreamMonitor(os, null);
    }
}

afterExample:
import java.io.ByteArrayOutputStream;
import java.io.OutputStream;
import java.nio.charset.Charset;
import org.eclipse.debug.internal.core.InputStreamMonitor;

public class Example {
    public void test() {
        OutputStream os = new ByteArrayOutputStream();
        // The replacement uses Charset.forName() directly, avoiding the deprecated constructor
        InputStreamMonitor monitor1 = new InputStreamMonitor(os, Charset.forName("UTF-8"));
        // Behavior for null encoding string is preserved (throws NullPointerException)
        InputStreamMonitor monitor2 = new InputStreamMonitor(os, Charset.forName(null));
    }
}

negativeExample:
import java.io.ByteArrayOutputStream;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import org.eclipse.debug.internal.core.InputStreamMonitor;

public class Example {
    public void test() {
        OutputStream os = new ByteArrayOutputStream();
        // Already uses a Charset constant, so should not match
        InputStreamMonitor monitor1 = new InputStreamMonitor(os, StandardCharsets.UTF_8);
        // Different constructor signature (takes Charset directly), should not match
        InputStreamMonitor monitor2 = new InputStreamMonitor(os, (java.nio.charset.Charset) null);
        // Another constructor (takes only OutputStream), should not match
        InputStreamMonitor monitor3 = new InputStreamMonitor(os);
    }
}
